-- Fictional identities only. All application and identity writes roll back.
begin;
insert into auth.users(id,email,email_confirmed_at) select ('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,'study-'||n||'@example.invalid',now()-interval '1 day' from unnest(array[101,103,104,105,107])n;
insert into auth.sessions(id,user_id,created_at) select ('aaaaaaaa-aaaa-4aaa-8aaa-'||lpad(n::text,12,'0'))::uuid,('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,now()-interval '1 hour' from unnest(array[101,103,104,105,107])n;
insert into app_private.account_links(member_id,auth_user_id,username) select ('44444444-4444-4444-8444-'||lpad(n::text,12,'0'))::uuid,('99999999-9999-4999-8999-'||lpad(n::text,12,'0'))::uuid,'study_'||n from unnest(array[101,103,104,105,107])n;
create function pg_temp.login(n integer) returns void language plpgsql as $$begin
 perform set_config('request.jwt.claim.sub','99999999-9999-4999-8999-'||lpad(n::text,12,'0'),true);
 perform set_config('request.jwt.claims',jsonb_build_object('session_id','aaaaaaaa-aaaa-4aaa-8aaa-'||lpad(n::text,12,'0'))::text,true);
end $$;
create function pg_temp.pass(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'STUDY PASS: %',label;end $$;
create function pg_temp.denied(stmt text,expected text,label text) returns void language plpgsql as $$declare actual text;begin begin execute stmt;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from expected then raise exception 'FAIL: % expected % got %',label,expected,actual;end if;raise notice 'STUDY PASS: %',label;end $$;
create function pg_temp.tomorrow() returns date language sql stable as $$select (now() at time zone 'America/Los_Angeles')::date+1$$;
create function pg_temp.command(req uuid,resource integer,s integer,e integer) returns jsonb language sql stable as $$select jsonb_build_object('requestId',req,'action','reserve','resourceId','92000000-0000-4000-8000-'||lpad(resource::text,12,'0'),'day',pg_temp.tomorrow()::text,'start',s,'end',e,'purpose','contact','detail','Private Example Contact')$$;
update app_private.app_modules set status='approved',approved_at=now() where module_key='study-rooms';
insert into app_private.module_access_grants(member_id,module_id,permission,granted_at,reason) select ('44444444-4444-4444-8444-'||lpad(n::text,12,'0'))::uuid,'91000000-0000-4000-8000-000000000001',case n when 101 then 'manager' else 'viewer' end,now()-interval '1 day','Fictional study-module test grant' from unnest(array[101,103,107])n;

create function pg_temp.bundle(req integer,resources integer[],s integer default 780,e integer default 840) returns jsonb language sql stable as $$
 select (pg_temp.command(('98000000-0000-4000-8000-'||lpad(req::text,12,'0'))::uuid,resources[1],s,e)-'resourceId')||jsonb_build_object('resourceIds',(select jsonb_agg('92000000-0000-4000-8000-'||lpad(n::text,12,'0')) from unnest(resources)n))
$$;
select pg_temp.login(107);set local role authenticated;
select set_config('test.bundle',public.study_room_command(pg_temp.bundle(1,array[1,11,21]))::text,true);
select set_config('test.bid',current_setting('test.bundle')::jsonb->>'bookingId',true);
select pg_temp.pass(jsonb_array_length(current_setting('test.bundle')::jsonb->'resourceIds')=3,'bundle confirms all three resources');
select pg_temp.pass(public.study_room_command(pg_temp.bundle(1,array[1,11,21]))=current_setting('test.bundle')::jsonb,'bundle retry returns same receipt');
select pg_temp.denied('select public.study_room_command(pg_temp.bundle(1,array[2,12,22]))','22023','idempotency key cannot substitute other resources');
select pg_temp.denied('select app_private.study_room_command_r2(''{}'')','42501','legacy command cannot bypass bundle enforcement');
select pg_temp.denied('select app_private.study_room_schedule_r2(pg_temp.tomorrow())','42501','legacy schedule is not another public boundary');
select pg_temp.denied('select app_private.study_resource_ids(current_setting(''test.bid'')::uuid)','42501','bundle helper is not directly readable');
select pg_temp.denied('select * from app_private.study_booking_resources','42501','raw bundle membership is private');
select pg_temp.pass(jsonb_array_length(public.member_module_home()->'activities')=1,'combined reservation creates exactly one activity');
select pg_temp.pass(not(public.member_module_home()::text like '%Private Example Contact%'),'combined activity redacts private details');
reset role;
select pg_temp.pass((select count(*)=1 from app_private.study_bookings),'bundle has one reservation identity');
select pg_temp.pass((select count(*)=3 from app_private.study_booking_resources),'bundle claims three memberships');
select pg_temp.pass((select count(*)=6 from app_private.study_slots),'bundle claims exact half-hour slots');
select pg_temp.pass((select count(*)=1 from app_private.study_request_receipts),'retry creates no duplicate receipt');
select pg_temp.pass((select rowsecurity from pg_tables where schemaname='app_private' and tablename='study_booking_resources'),'bundle membership has RLS');
select pg_temp.login(103);set local role authenticated;
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'bookings')b where b->>'id'=current_setting('test.bid') and b->>'label'='Reserved' and not(b?'detail') and not(b?'purpose')),'cross-group bundle hides identity and purpose');
select pg_temp.pass(public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow())->>'total'='0','ordinary history excludes other owners');
select pg_temp.denied('select public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow(),0,true)','42501','history oversight needs explicit manager grant');
select pg_temp.denied($q$select public.study_room_command(jsonb_build_object('requestId',gen_random_uuid(),'action','cancel','bookingId',current_setting('test.bid'),'expectedVersion',1,'reason','Another owner attempt'))$q$,'42501','another member cannot cancel a bundle');
select pg_temp.denied('select public.study_room_command(pg_temp.bundle(2,array[2,11,22]))','23505','busy accessory rejects entire new reservation');
select public.study_room_command(pg_temp.bundle(3,array[12,22]));
reset role;
select pg_temp.pass((select count(*)=0 from app_private.study_slots where resource_id='92000000-0000-4000-8000-000000000002'),'failed accessory reservation leaves primary unclaimed');
select pg_temp.pass((select count(*)=2 from app_private.study_bookings),'failed bundle creates no phantom booking');
select pg_temp.login(107);set local role authenticated;
select pg_temp.denied('select public.study_room_command(pg_temp.bundle(4,array[3,4]))','22023','two resources of the same kind rejected');
select pg_temp.denied('select public.study_room_command(pg_temp.bundle(5,array[3,3]))','22023','duplicate resource rejected');
select pg_temp.denied('select public.study_room_command(pg_temp.bundle(6,array[3,99]))','22023','unknown accessory rejected');
select pg_temp.denied($q$select public.study_room_command(pg_temp.bundle(7,array[3,13])||jsonb_build_object('memberId','44444444-4444-4444-8444-000000000103'))$q$,'22023','bundle cannot impersonate a different member');
select pg_temp.denied($q$select public.study_room_command(pg_temp.bundle(8,array[2,12,23])||jsonb_build_object('action','reschedule','bookingId',current_setting('test.bid'),'expectedVersion',1,'reason','Accessory conflict test'))$q$,'23505','failed reschedule leaves original bundle');
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_schedule(pg_temp.tomorrow())->'bookings')b where b->>'id'=current_setting('test.bid') and b->>'version'='1' and b->'resourceIds' ? '92000000-0000-4000-8000-000000000001'),'failed move retains identity version and old primary');
select set_config('test.move',(pg_temp.bundle(9,array[2,13,23])||jsonb_build_object('action','reschedule','bookingId',current_setting('test.bid'),'expectedVersion',1,'reason','Move all resources together'))::text,true);
select pg_temp.pass(public.study_room_command(current_setting('test.move')::jsonb)->>'version'='2','whole bundle reschedules in one revision');
select pg_temp.pass(public.study_room_command(current_setting('test.move')::jsonb)->>'bookingId'=current_setting('test.bid'),'move retry retains booking identity');
select pg_temp.denied($q$select public.study_room_command(current_setting('test.move')::jsonb||jsonb_build_object('requestId',gen_random_uuid()))$q$,'40001','stale bundle editor rejected');
select pg_temp.denied($q$select public.study_room_command(pg_temp.command(gen_random_uuid(),4,780,840)||jsonb_build_object('action','reschedule','bookingId',current_setting('test.bid'),'expectedVersion',2,'reason','Legacy editor drops accessories'))$q$,'22023','legacy editor cannot silently drop accessories');
reset role;
select pg_temp.pass((select count(*)=0 from app_private.study_slots where resource_id in ('92000000-0000-4000-8000-000000000001','92000000-0000-4000-8000-000000000011','92000000-0000-4000-8000-000000000021')),'move frees every old resource');
select pg_temp.pass((select count(*)=6 from app_private.study_slots where booking_id=current_setting('test.bid')::uuid),'move claims every new resource');
select pg_temp.pass((select count(*)=1 from app_private.study_change_history where target_id=current_setting('test.bid')::uuid),'one move creates one history event');
select pg_temp.pass((select jsonb_array_length(previous->'resourceIds')=3 and jsonb_array_length(next->'resourceIds')=3 from app_private.study_change_history where target_id=current_setting('test.bid')::uuid),'history records before and after resource sets');
select pg_temp.login(101);set local role authenticated;
select pg_temp.pass(public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow(),0,true)->>'total'='2','explicit manager can oversee both owners');
select pg_temp.pass(public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow(),0,true)::text like '%Private Example Contact%','private purpose visible to explicit manager');
select pg_temp.denied($q$select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','closure.add','resourceId','92000000-0000-4000-8000-000000000013','day',pg_temp.tomorrow()::text,'start',780,'end',840,'reason','Cannot displace bundled board'))$q$,'23505','accessory closure cannot evict bundle');
select pg_temp.denied($q$select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','resource.update','resourceId','92000000-0000-4000-8000-000000000013','name','Board 3','active',false,'expectedVersion',1,'reason','Cannot disable bundled board'))$q$,'23505','accessory cannot be disabled while booked');
select public.study_room_admin(jsonb_build_object('requestId',gen_random_uuid(),'action','resource.update','resourceId','92000000-0000-4000-8000-000000000013','name','Renamed Board','active',true,'expectedVersion',1,'reason','Inventory label correction'));
reset role;select pg_temp.login(107);set local role authenticated;
select pg_temp.pass(public.member_module_home()::text like '%Renamed Board%','accessory rename updates one safe activity');
select pg_temp.denied('select public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow()+31)','22023','history queries are bounded to 31 days');
select pg_temp.denied('select public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow(),-1)','22023','negative history offset rejected');
reset role;
create or replace function app_private.study_clock() returns timestamptz language sql volatile set search_path='' as $$select (((now() at time zone 'America/Los_Angeles')::date+1)+time '13:15') at time zone 'America/Los_Angeles'$$;
select pg_temp.login(107);set local role authenticated;
select set_config('test.early',jsonb_build_object('requestId',gen_random_uuid(),'action','end_early','bookingId',current_setting('test.bid'),'expectedVersion',2,'reason','Fictional session completed')::text,true);
select pg_temp.pass(public.study_room_command(current_setting('test.early')::jsonb)->>'releasedFrom'='810','early end releases all resources from next full interval');
select pg_temp.pass(public.study_room_command(current_setting('test.early')::jsonb)->>'version'='3','early-end retry is idempotent');
reset role;
select pg_temp.pass((select count(*)=3 from app_private.study_slots where booking_id=current_setting('test.bid')::uuid and minute=780),'early end retains current interval for all resources');
select pg_temp.pass((select count(*)=0 from app_private.study_slots where booking_id=current_setting('test.bid')::uuid and minute>=810),'early end releases all remaining resource slots');
select pg_temp.pass((select count(*)=3 from app_private.study_booking_resources where booking_id=current_setting('test.bid')::uuid),'ended bundle retains full membership history');
select pg_temp.login(107);set local role authenticated;
select pg_temp.pass(exists(select 1 from jsonb_array_elements(public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow())->'bookings')b where b->>'id'=current_setting('test.bid') and b->>'originalEnd'='840' and b->>'end'='810' and b->>'state'='ended'),'history preserves original and released end times');
reset role;select pg_temp.login(103);set local role authenticated;
select set_config('test.cancelbid',(public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow())->'bookings'->0->>'id'),true);
select public.study_room_command(jsonb_build_object('requestId',gen_random_uuid(),'action','cancel','bookingId',current_setting('test.cancelbid'),'expectedVersion',1,'reason','Fictional cancellation of bundle'));
reset role;
select pg_temp.pass((select count(*)=0 from app_private.study_slots where booking_id=current_setting('test.cancelbid')::uuid),'cancellation frees every bundled resource');
select pg_temp.pass((select count(*)=2 from app_private.study_booking_resources where booking_id=current_setting('test.cancelbid')::uuid),'cancellation preserves bundled inventory history');
select pg_temp.login(103);set local role authenticated;
select pg_temp.pass((public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow())->'bookings'->0->>'cancelReason')='Fictional cancellation of bundle','owner can read cancellation detail');
reset role;select pg_temp.login(104);set local role authenticated;
select pg_temp.denied('select public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow())','42501','member without module grant cannot read history');
select pg_temp.denied('select public.study_room_command(pg_temp.bundle(10,array[4,14,21],810,840))','42501','ungranted identity cannot create a bundle');
reset role;
-- Retrospective reads remain available after the booking day but stay private.
create or replace function app_private.study_clock() returns timestamptz language sql volatile set search_path='' as $$select now()+interval '45 days'$$;
select pg_temp.login(107);set local role authenticated;
select pg_temp.pass(public.study_room_history(pg_temp.tomorrow(),pg_temp.tomorrow())->>'total'='1','old owner history stays accessible outside booking horizon');
reset role;
set local role anon;
select pg_temp.denied('select public.study_room_history(current_date,current_date)','42501','anonymous history denied at function boundary');
select pg_temp.denied('select public.study_room_command(''{}'')','42501','anonymous bundle write denied at function boundary');
reset role;
set constraints all immediate;
select pg_temp.pass(true,'all deferred bundle membership constraints validate');
rollback;
